package com.badrulamin.University_Management.entity;  import jakarta.persistence.*; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.NotNull; import lombok.AllArgsConstructor; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import com.fasterxml.jackson.annotation.JsonProperty;  import java.time.LocalDate; import java.time.LocalTime;  @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Entity @Table(name = "faculty_attendance") public class FacultyAttendance extends BaseEntity {      @NotNull     @ManyToOne(fetch = FetchType.LAZY)     @JoinColumn(name = "faculty_id", nullable = false)     private Faculty faculty;      @NotNull     @Column(nullable = false)     private LocalDate attendanceDate;      @NotBlank     @Column(nullable = false)     private String status;      private LocalTime checkIn;      private LocalTime checkOut;      private String remarks;      @JsonProperty("facultyId")     public void setFacultyId(Long id) {         if (id != null) {             this.faculty = new Faculty();             this.faculty.setId(id);         }     }      @JsonProperty     public Long getFacultyId() {         return this.faculty != null ? this.faculty.getId() : null;     } }